module.exports = function() {
  const tokens = JSON.parse(process.env.AEL_TOKENS);
  const lines = [
    '//',
    '// AEL Design System — Swift Token Constants',
    '// Generated by 09-Build/generators/swift-generator.js',
    '// Source: 06-Implementation/tokens/',
    '// DO NOT EDIT — regenerate via: node 09-Build/build.js',
    '//',
    '',
    'import SwiftUI',
    '',
    'public enum AELTokens {'
  ];

  const categorized = {};
  for (const tok of Object.values(tokens)) {
    if (!categorized[tok.category]) categorized[tok.category] = [];
    categorized[tok.category].push(tok);
  }

  for (const category of Object.keys(categorized).sort()) {
    const catName = category.charAt(0).toUpperCase() + category.slice(1).replace(/-./g, x => x[1].toUpperCase());
    lines.push(`    public enum ${catName} {`);

    for (const tok of categorized[category].sort((a, b) => a.id.localeCompare(b.id))) {
      const propName = swiftSafeName(
        tok.id.replace(/^TK-\w+-/, '').replace(/-./g, x => x[1].toUpperCase())
      );
      let val = tok.value;

      if (tok.type === 'color') {
        // Note: the nested enum is itself named `Color`, which shadows
        // SwiftUI.Color inside the enum body — the type must be fully
        // qualified or the generated code will not compile.
        lines.push(`        /// ${tok.role}`);
        lines.push(`        public static let ${propName}: SwiftUI.Color = SwiftUI.Color(hex: "${val}")`);
      } else if (tok.type === 'dimension') {
        const pxVal = parseFloat(val);
        lines.push(`        /// ${tok.role}`);
        lines.push(`        public static let ${propName}: CGFloat = ${pxVal}`);
      } else if (tok.type === 'number') {
        lines.push(`        /// ${tok.role}`);
        lines.push(`        public static let ${propName}: CGFloat = ${val}`);
      } else if (tok.type === 'fontFamily') {
        lines.push(`        /// ${tok.role}`);
        lines.push(`        public static let ${propName}: String = "${val.split(',')[0].trim().replace(/'/g, '')}"`);
      } else if (tok.type === 'duration') {
        const msVal = parseFloat(val) / 1000;
        lines.push(`        /// ${tok.role}`);
        lines.push(`        public static let ${propName}: TimeInterval = ${msVal}`);
      } else if (tok.type === 'easing') {
        lines.push(`        /// ${tok.role}`);
        lines.push(`        public static let ${propName}: String = "${val}"`);
      } else if (tok.type === 'shadow') {
        lines.push(`        /// ${tok.role}`);
        lines.push(`        public static let ${propName}: String = "${val}"`);
      }
    }

    lines.push(`    }`);
    lines.push('');
  }

  lines.push('}');

  return lines.join('\n');
};

// Swift identifiers cannot start with a digit (e.g. token `2xl`). Prefix
// leading digits with an underscore so the generated enum always compiles.
function swiftSafeName(name) {
  return /^[0-9]/.test(name) ? '_' + name : name;
}
